package com.ecommerce.controller;
import com.ecommerce.dto.ApiDtos.*; import com.ecommerce.service.ProductService; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/products")
public class ProductController {private final ProductService service;public ProductController(ProductService s){service=s;}@GetMapping Page<ProductResponse> all(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="24")int size,@RequestParam(defaultValue="newest")String sort){return service.all(q,category,page,size,sort);}@GetMapping("/{id}")ProductResponse one(@PathVariable Long id){return service.one(id);}@PreAuthorize("hasRole('SELLER')") @GetMapping("/my")List<ProductResponse> mine(Authentication a){return service.mine(a.getName());}@PostMapping ProductResponse create(Authentication a,@Valid @RequestBody ProductRequest r){return service.create(r,a.getName());}@PutMapping("/{id}")ProductResponse update(Authentication a,@PathVariable Long id,@Valid @RequestBody ProductRequest r){return service.update(id,r,a.getName());}@DeleteMapping("/{id}")void delete(Authentication a,@PathVariable Long id){service.delete(id,a.getName());}}
